Translate("ptBR", "zanzil-the-outcast", {
	title = "Zanzil, o Pária",
	subtitle = "O Médico Bruxo Exilado",
	found = "As Ruínas de Aboraz, na Praia Cristalina",
	hint = [=[Procure o médico bruxo pária nas ruínas a nordeste da Angra do Butim.]=],
	allegiance = "Seus próprios seguidores",
	aliases = { "Zanzil" },
	sections = {
		{
			title = "Resumo",
			text = [=[Zanzil é um médico bruxo troll que sua própria tribo expulsou. Seus líderes o temiam, e com razão. Ele sabe dobrar a mente dos outros. Das plantas da selva, prepara uma mistura que embota a vontade de quem a bebe e fortalece seu corpo, e seus seguidores nas ruínas de {link:ruins-of-aboraz-and-jubuwal}Aboraz{/link} e Jubuwal vivem dela. Os mortos que vagam por lá talvez também lhe devam seu estado.]=],
		},
		{
			title = "Importância",
			text = [=[O ofício de Zanzil se espalhou para além da selva. Os goblins da {link:booty-bay}Angra do Butim{/link} compram amostras de sua mistura, e um deles aprendeu a transformá-la numa bebida forte para tramas próprias. Muito ao norte, os espiões do {link:si-7}SI:7{/link} descobriram que os trolls de Zanzil sabem erguer os mortos com veneno, e que o segredo passou às mãos da {link:defias-brotherhood}Irmandade Défias{/link}. Na {link:tarren-mill}Serraria Tarren{/link}, {link:serge-hinott}Serge Hinott{/link} estudou a loucura que seus venenos provocam.]=],
		},
		{
			title = "Feitos",
			text = [=[• Foi exilado por sua tribo por causa de seu poder sobre outras mentes.
• Lidera seus seguidores nas ruínas de {link:ruins-of-aboraz-and-jubuwal}Aboraz{/link} e Jubuwal.
• Tomou o menino {link:darkspear-trolls}Lançanegra{/link} {link:yenniku}Yenniku{/link} e o dominou, corpo e alma.
• Diz-se que suas poções erguem os mortos.]=],
		},
	},
	chapters = {
		{
			title = "A Mistura",
			hint = "Tome dos seguidores de Zanzil a poção que os prende.",
			text = [=[{link:crank-fizzlebub}Crank Fizzlebub{/link} explicou o assunto com clareza a quem quis ouvir. Uma mistura capaz de suprimir a vontade e endurecer o corpo vale muito para quem quer governar os outros. Ele pagava bem por ela, e um pouco mais pelo silêncio.]=],
		},
		{
			title = "A Alma Roubada",
			hint = "Liberte o jovem Lançanegra das garras do médico bruxo.",
			text = [=[O domínio de Zanzil sobre {link:yenniku}Yenniku{/link} era tão forte que só a magia mais potente poderia quebrá-lo. Os médicos bruxos dos {link:darkspear-trolls}Lançanegra{/link} fizeram essa magia a partir da joia de um {link:ogres}ogro{/link}. Quando a gema de alma se fechou sobre o espírito de Yenniku, Zanzil perdeu o mais precioso de seus escravos.]=],
		},
	},
	mentions = {
		{ text = "O Segredo de Zanzil" },
		{ text = "O Destino de {link:yenniku}Yenniku{/link}" },
		{ text = "Salvando {link:yenniku}Yenniku{/link}" },
		{ text = "De Volta à {link:booty-bay}Angra do Butim{/link}" },
