		{ text = "Dívidas de Vodu" },
		{ text = "A Torre de Klaven" },
	},
	bonds = {
		{ id = "yenniku", name = "Yenniku", note = "seu escravo" },
		{ id = "crank-fizzlebub", name = "Crank Fizzlebub", note = "compra sua mistura" },
		{ id = "nimboya", name = "Nimboya", note = "busca tirar Yenniku dele" },
