	subtitle = "Companheiro de Nesingwary",
	found = "Expedição do Rosarães",
	hint = [=[Fale com o anão que recebe os visitantes no acampamento de Nesingwary.]=],
	allegiance = "Expedição do Rosarães",
	aliases = { "Barnil" },
	sections = {
		{
